from apps.portfolio.services.capital_cockpit import build_capital_cockpit

class CapitalCockpitView(APIView):
    permission_classes = [IsAuthenticated]
    def get(self, request):
        portfolio_id = request.query_params.get('portfolio')
        qs = Portfolio.objects.filter(tenant=request.tenant)
        portfolio = qs.filter(id=portfolio_id).first() if portfolio_id else qs.first()
        # auto-create default like MonthlyReportView so the page never 404s
        if not portfolio:
            portfolio = Portfolio.objects.create(tenant=request.tenant, name='Default', capital=500_000, mode='paper')
        return Response(build_capital_cockpit(request.tenant, portfolio))

import { useQuery } from '@tanstack/react-query';
import { fetchCapitalCockpit, type CapitalCockpit } from '@/lib/api';
import { Card, KPI } from '@/components/ui';
import { fmtInr, fmtPct } from '@/lib/utils';

export function CapitalCockpit() {
  const { data, isLoading } = useQuery<CapitalCockpit>({
    queryKey: ['capital-cockpit'],
    queryFn: fetchCapitalCockpit,
    refetchInterval: 15_000,
  });
  if (isLoading || !data) return <Card>Loading…</Card>;
  return (
    <Card title='Capital & Leverage'>
      <div className='grid grid-cols-2 md:grid-cols-6 gap-3'>
        <KPI label='Capital' value={fmtInr(data.total_capital)} />
        <KPI label='Deployed' value={fmtInr(data.deployed_capital)} />
        <KPI label='Free Margin' value={fmtInr(data.free_margin)} />
        <KPI label='Notional' value={fmtInr(data.notional_exposure)} />
        <KPI label='Δ-Adj Notional' value={fmtInr(data.delta_adjusted_exposure)} />
        <KPI label='Leverage' value={`${data.leverage_ratio.toFixed(2)}x`} tone={data.leverage_ratio > 3 ? 'warn' : 'ok'} />
      </div>
      <BucketTable rows={Object.entries(data.by_bucket)} />
    </Card>
  );
}

export interface CapitalCockpit {
  as_of: string;
  total_capital: number;
  deployed_capital: number;
  free_margin: number;
  notional_exposure: number;
  delta_adjusted_exposure: number;
  leverage_ratio: number;
  by_bucket: Record<string, { notional: number; delta_notional: number; count: number }>;
}

export async function fetchCapitalCockpit(portfolioId?: string): Promise<CapitalCockpit> {
  const { data } = await api.get<CapitalCockpit>('/portfolios/capital-cockpit/', {
    params: portfolioId ? { portfolio: portfolioId } : undefined,
  });
  return data;
}

