from apps.portfolio.services.correlation_matrix import build_correlation_report

class CorrelationMatrixView(APIView):
    permission_classes = [IsAuthenticated]
    def get(self, request):
        portfolio_id = request.query_params.get('portfolio')
        force = request.query_params.get('force') in ('1','true')
        qs = Portfolio.objects.filter(tenant=request.tenant)
        if portfolio_id: qs = qs.filter(id=portfolio_id)
        portfolio = qs.first() or Portfolio.objects.create(tenant=request.tenant, name='Default', capital=500_000, mode='paper')
        return Response(build_correlation_report(request.tenant, portfolio, force=force))

export type CorrelationReport = {
  symbols: string[];
  matrix: number[][];
  independent_bets: number;
  sector_weights: Record<string, number>;
  factor_weights: Record<string, number>;
  as_of: string;
};
export async function fetchCorrelationMatrix(force=false): Promise<CorrelationReport> {
  const { data } = await api.get<CorrelationReport>('/portfolios/correlation/', { params: force ? { force: 1 } : {} });
  return data;
}

import { useQuery } from '@tanstack/react-query';
import { fetchCorrelationMatrix, CorrelationReport } from '@/lib/api';
import { Card, KPI } from '@/components/ui';

export function CorrelationMatrix() {
  const { data, isLoading, error } = useQuery({
    queryKey: ['portfolio','correlation'], queryFn: () => fetchCorrelationMatrix(),
    refetchInterval: 60_000,
  });
  if (isLoading) return <Skeleton/>;
  if (error || !data?.symbols.length) return <EmptyState msg='No open positions'/>;
  return (
    <div className='grid gap-4'>
      <KPI label='Independent Bets' value={data.independent_bets}/>
      <Heatmap symbols={data.symbols} matrix={data.matrix} colorScale={rhoColor}/>
      <ConcentrationBars title='Sector' weights={data.sector_weights}/>
      <ConcentrationBars title='Factor' weights={data.factor_weights}/>
    </div>
  );
}
// rhoColor: -1 red → 0 neutral → +1 green; cells show 2-decimal rho on hover
